def G_egg_type(m):
 r=random.randint(0,999)
 rar=4 if r<4+2*m else 3 if r<30+10*m else 2 if r<110+25*m else 1 if r<330+40*m else 0
 return random.choice([i for i in range(20)if G_DT[i][2]==rar])
def G_art(b,x,y,s,P):
 for i in range(0,len(b),8):
  c=P[b[i+1]]
  a1,a2,a3,a4,a5,a6=(b[i+2],b[i+3],b[i+4],b[i+5],b[i+6],b[i+7])
  if b[i]==0:
   rect(x+a1*s,y+a2*s,a3*s,a4*s,c)
  elif b[i]==1:
   circ(x+a1*s,y+a2*s,a3*s,c)
  else:
   col(c)
   fill_poly([x+a1*s,x+a3*s,x+a5*s],[y+a2*s,y+a4*s,y+a6*s])
def G_drag(x,y,s,t,c,head=0,body=0):
 P=G_PAL+[lt(c,0.45),dk(c,0.6),c]+G_PAL2+[lt(c,0.2),dk(c,0.4)]+G_PAL3
 G_art(G_ARTB,x,y,s,P)
 G_art(G_ARTF[t],x,y,s,P)
 w,b=(G_ARTW[2*t],G_ARTW[2*t+1])
 G_art(bytes((2,w,24,26,40,10,37,28,2,b,40,10,28,27,30,27,2,b,40,10,33,28,35,28,2,17,23,26,40,9,26,26,1,17,26,27,3,0,0,0,2,1,40,9,42,7,41,11)),x,y,s,P)
 G_art(G_ARTL,x,y,s,P)
 G_art(G_ARTO[t],x,y,s,P)
 if body:
  G_art(G_ARTG[body],x,y,s,P)
 if head:
  G_art(G_ARTG[head],x,y,s,P)
def G_draw_map(g,after_msg=False):
 r0,r1=(0,9)
 if after_msg:
  r0=max(0,(MSG[0]-20)//G_T)
  r1=min(9,(MSG[0]+MSG[1]-20)//G_T+1)
 else:
  cls()
  G_HUD[0]=None
 G_cells(g,[(x,y)for y in range(r0,r1)for x in range(16)],r0<=g.y<r1)
 G_hud(g)
def G_save(g):
 s=[4,g.coins,g.own,g.book,g.dread]+(g.bag+[-1]*5)[:5]
 for d in g.pen:
  p=G_PAINT.index(d[6])+1 if d[6]in G_PAINT and d[6]!=G_DT[d[1]][3]else 0
  n=0
  for ch in d[0].upper():
   n=n*27+G_ABC.index(ch)+1
  s+=[n,d[1],d[2],d[5],p*200+d[7]*20+d[8]]
 try:
  from ti_system import store_list
  store_list('DRG',s)
 except Exception:
  pass
def G_quest_step(g,kind,what):
 q=g.quest
 if q is None or q[0]!=kind or(q[1]is not None and q[1]!=what):
  return
 q[3]+=1
 if q[3]>=q[2]:
  g.coins+=q[4]
  g.quest=None
  message(['You finished:',q[5],'+'+str(q[4])+' coins!'],'Quest done!')
def G_put_egg(g,t,near):
 mp=g.maps[g.m]
 for n in range(30):
  if near:
   x=g.x+random.randint(-1,1)
   y=g.y+random.randint(-1,1)
  else:
   x=random.randint(1,14)
   y=random.randint(1,7)
  if 0<=x<16 and 0<=y<9 and(mp[y][x]in '."')and((x,y)!=(g.x,g.y))and(near or abs(x-g.x)+abs(y-g.y)>3):
   mp[y][x]='E'
   G_EGGS[g.m,x,y]=t
   G_cells(g,[(x,y)],False)
   return True
 return False
def G_play():
 g=G_Game()
 g.maps=[[list(r)for r in mp]for mp in G_MAPS]
 G_EGGS.clear()
 for m in range(3):
  for y in range(9):
   for x in range(16):
    if G_MAPS[m][y][x]=='E':
     G_EGGS[m,x,y]=random.randint(0,6)if m==0 else G_egg_type(m)
 g.m,g.x,g.y=(0,3,2)
 g.hp=g.mhp=30
 g.pen=[]
 g.pick=None
 g.ride=None
 g.bag=[]
 g.warm=12
 g.coins=0
 g.own=0
 g.book=0
 g.quest=None
 g.seen=0
 g.spawn=100
 g.dread=0
 G_load(g)
 steps=0
 G_draw_map(g)
 if g.pen or g.bag:
  message(['Welcome back! You have',str(len(g.pen))+' dragons, '+str(g.coins)+' coins.'],'DRAGON TAMER')
 else:
  message(['The Shadow Wyrm scared','the dragons away. Find','eggs and raise a team!'],'DRAGON TAMER')
 G_draw_map(g,True)
 while True:
  k=wkey()
  if k==CLR:
   if message(['ENTER: save and quit','CLEAR: keep going'],'Quit?')==OK:
    G_rest(g)
    G_save(g)
    return
   G_draw_map(g,True)
   continue
  if k in(OK,SECOND):
   c=G_menu(g)
   if c:
    (G_backpack if c==1 else G_book)(g)
    G_draw_map(g)
   continue
  dx,dy={LEFT:(-1,0),RIGHT:(1,0),UP:(0,-1),DOWN:(0,1)}.get(k,(0,0))
  if dx==0 and dy==0:
   continue
  nx,ny=(g.x+dx,g.y+dy)
  if nx<0 or nx>15:
   m=g.m+(1 if nx>15 else-1)
   if 0<=m<3:
    ch=g.maps[m][ny][15-g.x]
    if ch!='T'and(ch not in '~L^'or g.ride is not None):
     g.m=m
     g.seen=max(g.seen,m)
     g.x=15-g.x
     G_draw_map(g)
   continue
  if ny<0 or ny>8:
   continue
  mp=g.maps[g.m]
  ch=mp[ny][nx]
  if ch=='T'or(ch in '~L^'and g.ride is None):
   continue
  if ch=='B':
   if G_battle(g,G_BOSS):
    G_win(g)
    return
   if g.hp<=0:
    return
   G_draw_map(g)
   continue
  if ch=='E'and(len(g.bag)>=5 or len(g.pen)+len(g.bag)>=10):
   G_draw_map(g)
   message(['Your backpack is full.']if len(g.bag)>=5 else['No room in your pen.','Let a dragon go first.'],'Egg')
   G_draw_map(g,True)
   continue
  ox,oy=(g.x,g.y)
  g.x,g.y=(nx,ny)
  if ch=='E':
   mp[ny][nx]='.'
   G_cells(g,[(ox,oy),(nx,ny)],True)
   e=G_EGGS.pop((g.m,nx,ny),0)
   if not g.bag:
    g.warm=12
   g.bag.append(e)
   G_hud(g)
   message(['You found an egg with',G_RARE[G_DT[e][2]]+" spots! It's in",'your backpack.'],'An egg!')
   G_draw_map(g,True)
   continue
  if ch=='H':
   while True:
    c=G_nest(g)
    if not c:
     break
    (G_backpack if c==1 else G_book)(g)
   G_draw_map(g)
   continue
  G_cells(g,[(ox,oy),(nx,ny)],True)
  if g.bag:
   g.warm-=1
   if g.warm<=0:
    G_hatch(g)
    continue
  g.spawn-=1
  if g.spawn<=0:
   g.spawn=random.randint(100,200)
   if not any((q[0]==g.m for q in G_EGGS)):
    G_put_egg(g,G_egg_type(g.m),False)
  G_hud(g)
  steps+=1
  if g.dread>0:
   g.dread-=1
  if(g.dread==1 or(not g.dread and steps>3 and(random.random()<G_EVIL)))and(not g.book>>25&1)and any((G_DT[d[1]][2]>=3 for d in g.pen)):
   steps=0
   if not G_evil(g):
    return
   continue
  if ch=='"'and steps>3 and(random.random()<0.2):
   steps=0
   if not G_battle(g,random.choice(G_FOES[g.m])):
    return
   G_draw_map(g)
def G_back():
 G_play()
